import bpy
from mathutils import Vector
print('FILE='+bpy.data.filepath)
elev=bpy.data.collections.get('01 WORLD | ELEVADOR LACERDA | blockout v4')
if not elev: raise RuntimeError('elevador ativo ausente')
keys=['torre documental','hall piso terreo','parede lateral esquerda','parede lateral direita','passadico']
for key in keys:
    print('---'+key+'---')
    for o in elev.all_objects:
        if key in o.name.lower():
            local=[]
            if o.type=='MESH':
                local=[v.co.copy() for v in o.data.vertices]
            if local:
                xs=[p.x for p in local];ys=[p.y for p in local];zs=[p.z for p in local]
                print(o.name,'LOC',tuple(round(v,3) for v in o.location),'ROT',tuple(round(v,5) for v in o.rotation_euler),'LOCAL_BOUNDS',(round(min(xs),3),round(max(xs),3),round(min(ys),3),round(max(ys),3),round(min(zs),3),round(max(zs),3)))
            else:
                print(o.name,'LOC',tuple(round(v,3) for v in o.location),'ROT',tuple(round(v,5) for v in o.rotation_euler),'DIMS',tuple(round(v,3) for v in o.dimensions))
print('DIRECT_OBJECTS',len(elev.objects),'ALL_OBJECTS',len(elev.all_objects))
print('SHAFT_AXES_INSPECT_OK')
